Read the source table in A:D, group rows by the combined A/B/C key while summing D in first-seen order. Clear the output area, write the unique keys to G:I and the sums to J, then save plain values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

vws = vals["merge"]
ws = wb["merge"]

def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v

def key_part(v):
    if v is None:
        return ""
    if isinstance(v, str):
        return v.strip()
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return str(v).strip()

def to_number(v):
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return 0.0
        try:
            return float(s)
        except ValueError:
            return 0.0
    return 0.0

last_row = max(vws.max_row, 1000)

# Clear output rows G:J before writing results.
for r in range(2, last_row + 1):
    for c in range(7, 11):  # G, H, I, J
        ws.cell(row=r, column=c).value = None

# Keep/write headers corresponding to source columns A:D.
for out_c, in_c in ((7, 1), (8, 2), (9, 3), (10, 4)):
    v = vws.cell(row=1, column=in_c).value
    if v is None:
        v = ws.cell(row=1, column=out_c).value
    if v is not None:
        ws.cell(row=1, column=out_c).value = clean(v)

groups = {}
order = []

for r in range(2, vws.max_row + 1):
    a = vws.cell(row=r, column=1).value
    b = vws.cell(row=r, column=2).value
    c = vws.cell(row=r, column=3).value
    d = vws.cell(row=r, column=4).value

    if a is None and b is None and c is None and d is None:
        continue

    key = (key_part(a), key_part(b), key_part(c))
    if key not in groups:
        groups[key] = [0.0, clean(a), clean(b), clean(c)]
        order.append(key)

    groups[key][0] += to_number(d)

for i, key in enumerate(order, start=2):
    total, a_out, b_out, c_out = groups[key]
    if isinstance(total, float) and total.is_integer():
        total = int(total)

    ws.cell(row=i, column=7).value = a_out   # G: ID
    ws.cell(row=i, column=8).value = b_out   # H: Brand
    ws.cell(row=i, column=9).value = c_out   # I: type
    ws.cell(row=i, column=10).value = total  # J: Total

# Ensure remaining answer-region cells are empty.
for r in range(2 + len(order), last_row + 1):
    for c in range(7, 10):  # G:I
        ws.cell(row=r, column=c).value = None

wb.save(OUT)

print("unique_rows", len(order))
for key in order[:5]:
    print(key, groups[key][0])
